fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    // We only need to check parent indices from 0 to floor(n/2) - 1
    for i in 0..(n / 2) {
        let parent = a[i];
        let left_child_index = 2 * i + 1;
        let right_child_index = 2 * i + 2;

        // Check left child
        if left_child_index < n {
            if a[left_child_index] < parent {
                return false;
            }
        }

        // Check right child
        if right_child_index < n {
            if a[right_child_index] < parent {
                return false;
            }
        }
    }
    true
}